import { requestMessage } from '../requestError';

/** Черновик формы не связан с объектом строки. Ошибка сохраняет введённые значения. */
export default class CatalogEditorState {
  saving = false;
  uploading = false;
  error = '';
  constructor(initial, id, revision, api) {
    this.id = id;
    this.revision = revision;
    this.api = api;
    this.values = JSON.parse(JSON.stringify(initial));
  }
  text(key) {
    return String(this.values[key] ?? '');
  }
  number(key) {
    return Number(this.values[key] ?? 0);
  }
  flag(key) {
    return Boolean(this.values[key]);
  }
  get imageEndpoint() {
    return this.api.imageEndpoint ?? '/roleplay/admin/perk-image';
  }
  set(key, value) {
    this.values[key] = value;
  }
  async save() {
    if (this.saving || this.uploading) return false;
    this.saving = true;
    this.error = '';
    m.redraw();
    try {
      await this.api.save(this.id, this.revision, this.values);
      return true;
    } catch (error) {
      this.error = requestMessage(error, 'Не удалось сохранить. Проверь соединение и попробуй ещё раз.');
      return false;
    } finally {
      this.saving = false;
      m.redraw();
    }
  }
}
flarum.reg.add('maxcuso-roleplay', 'common/catalog/CatalogEditorState', CatalogEditorState);