import Modal from 'flarum/common/components/Modal';
import Button from 'flarum/common/components/Button';
/** При возврате замечание обязательно и на клиенте, и на сервере. */
export default class ReviewDecisionModal extends Modal {
  comment = '';
  className() {
    return 'RpReviewModal';
  }
  title() {
    return (this.attrs.action === 'approve' ? 'Одобрить' : 'Вернуть на исправление') + ' ' + (this.attrs.part === 'mechanics' ? 'техническую часть' : 'литературную часть');
  }
  content() {
    const state = this.attrs.profile;
    return m("form", {
      className: "Modal-body RpReview-form",
      onsubmit: event => {
        event.preventDefault();
        void this.save();
      }
    }, m("p", null, this.attrs.action === 'approve' ? 'Подтверди проверку актуальной версии анкеты.' : 'Укажи, что игроку нужно исправить.'), m("label", null, "\u0417\u0430\u043C\u0435\u0447\u0430\u043D\u0438\u044F", this.attrs.action === 'request_changes' ? ' (обязательно)' : '', m("textarea", {
      className: "FormControl",
      value: this.comment,
      maxlength: 4000,
      disabled: state.actionsBlocked,
      required: this.attrs.action === 'request_changes',
      oninput: event => {
        this.comment = event.target.value;
      }
    })), state.actionError && m("p", {
      role: "alert"
    }, state.actionError), state.retryAvailable ? m(Button, {
      type: "button",
      className: "Button Button--primary",
      loading: state.changing,
      disabled: state.changing,
      onclick: async () => {
        if (await state.retryOperation()) this.hide();
      }
    }, "\u041F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u044C \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435") : m(Button, {
      type: "submit",
      className: "Button Button--primary",
      loading: state.changing,
      disabled: state.actionsBlocked || this.attrs.action === 'request_changes' && !this.comment.trim()
    }, "\u041F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044C"));
  }
  async save() {
    if (await this.attrs.profile.changeReview(this.attrs.part, this.attrs.action, this.comment.trim())) this.hide();
  }
}
flarum.reg.add('maxcuso-roleplay', 'forum/profile/ReviewDecisionModal', ReviewDecisionModal);