import Component from 'flarum/common/Component';
import { FieldLabel } from './FormFields';

/** Раздел отделяется от соседнего одним отступом и тонкой линией.
 * Поля внутри остаются обычными полями: не создаём отдельные панели и вкладки. */

export default class EditorSection extends Component {
  view(vnode) {
    return m("section", {
      className: "RpEditorSection"
    }, m("h4", null, m(FieldLabel, {
      label: this.attrs.title,
      icon: this.attrs.icon
    })), vnode.children);
  }
}
flarum.reg.add('maxcuso-roleplay', 'common/catalog/components/EditorSection', EditorSection);