import Modal from 'flarum/common/components/Modal';
import Icon from 'flarum/common/components/Icon';
import { uiIcon } from '../../common/uiIcons';
import CharacterHistory from './CharacterHistory';
/** Показываем уже разрешённую сервером историю; окно не делает новых запросов. */
export default class CharacterHistoryModal extends Modal {
  className() {
    return 'Modal--small RpHistoryModal RpCharacterHistoryModal';
  }
  title() {
    return m('[', null, m(Icon, {
      name: uiIcon('actions.history')
    }), " \u0418\u0441\u0442\u043E\u0440\u0438\u044F \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u0436\u0430");
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, m(CharacterHistory, {
      events: this.attrs.events,
      lookups: this.attrs.lookups
    }));
  }
}
flarum.reg.add('maxcuso-roleplay', 'forum/profile/CharacterHistoryModal', CharacterHistoryModal);