import Modal from 'flarum/common/components/Modal';
import Icon from 'flarum/common/components/Icon';
import { text } from '../../common/catalogData';
import { uiIcon } from '../../common/uiIcons';
import { reviewParts, reviewStatus } from './reviewPresentation';
/** Используем уже загруженную историю проверки, не запрашивая полный журнал персонажа. */
export default class ReviewHistoryModal extends Modal {
  className() {
    return 'Modal--small RpHistoryModal RpReviewHistoryModal';
  }
  title() {
    return m('[', null, m(Icon, {
      name: uiIcon('actions.history')
    }), " \u0418\u0441\u0442\u043E\u0440\u0438\u044F \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0438");
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, m("div", {
      className: "RpHistory"
    }, !this.attrs.events.length ? m("p", null, "\u0418\u0441\u0442\u043E\u0440\u0438\u044F \u043F\u043E\u043A\u0430 \u043F\u0443\u0441\u0442\u0430.") : m("ul", null, this.attrs.events.map(event => {
      const details = event.details,
        part = text(details, 'part');
      const label = event.type === 'mechanics_updated' ? 'Техническая часть изменена и отправлена на проверку' : event.type === 'identity_corrected' ? 'Данные персонажа исправлены' : (reviewParts[part] ?? '') + ': ' + reviewStatus(part, text(details, 'after')).label;
      return m("li", {
        key: event.id
      }, m("strong", null, label), m("small", null, event.created_at), text(details, 'comment') && m("p", null, text(details, 'comment')));
    }))));
  }
}
flarum.reg.add('maxcuso-roleplay', 'forum/profile/ReviewHistoryModal', ReviewHistoryModal);