/** Статусы едины для анкеты, переключателя персонажей и истории профиля. */
export const characterStatuses = {
  creating: 'Создаётся',
  active: 'Активен',
  dead: 'Погиб',
  archived: 'В архиве'
};
export function characterStatus(value) {
  return characterStatuses[value] ?? 'Неизвестный статус';
}
flarum.reg.add('maxcuso-roleplay', 'common/character/characterStatus', { characterStatuses: characterStatuses,characterStatus: characterStatus, });