import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import { uiIcon } from '../uiIcons';
import EditorSection from '../catalog/components/EditorSection';
import { FieldLabel } from '../catalog/components/FormFields';
import { TimeField } from '../catalog/components/TimedFields';
/** Свойства редактируются как обычный текст. Перезарядка относится к своему свойству. */
export default class ItemPropertiesEditor extends Component {
  rows() {
    return Array.isArray(this.attrs.state.values.properties) ? this.attrs.state.values.properties : [];
  }
  update(index, patch) {
    this.attrs.state.set('properties', this.rows().map((row, current) => current === index ? {
      ...row,
      ...patch
    } : row));
  }
  view() {
    const rows = this.rows();
    return m(EditorSection, {
      title: "\u0421\u0432\u043E\u0439\u0441\u0442\u0432\u0430",
      icon: "fields.property"
    }, m("div", null, rows.map((property, index) => m("div", {
      key: index,
      className: "RpItemProperty"
    }, m("label", {
      className: "RpField"
    }, m(FieldLabel, {
      label: 'Свойство ' + (index + 1),
      icon: "fields.property"
    }), m("textarea", {
      className: "FormControl",
      rows: 3,
      required: true,
      maxlength: 20000,
      value: property.description,
      oninput: event => this.update(index, {
        description: event.target.value
      })
    })), m("div", null, TimeField({
      label: 'Перезарядка',
      icon: 'fields.cooldown',
      value: property.cooldown_value,
      unit: property.cooldown_unit,
      onValue: value => this.update(index, {
        cooldown_value: value
      }),
      onUnit: unit => this.update(index, {
        cooldown_unit: unit
      })
    })), m(Button, {
      className: "Button Button--icon RpProperty-remove",
      icon: uiIcon('actions.delete'),
      "aria-label": 'Убрать свойство ' + (index + 1),
      onclick: () => this.attrs.state.set('properties', this.rows().filter((_row, current) => current !== index))
    })))), m(Button, {
      className: "Button Button--link",
      icon: uiIcon('actions.create'),
      disabled: rows.length >= 100,
      onclick: () => this.attrs.state.set('properties', [...this.rows(), {
        description: '',
        cooldown_value: 0,
        cooldown_unit: 'turn'
      }])
    }, "\u0414\u043E\u0431\u0430\u0432\u0438\u0442\u044C \u0441\u0432\u043E\u0439\u0441\u0442\u0432\u043E"));
  }
}
flarum.reg.add('maxcuso-roleplay', 'common/editors/ItemPropertiesEditor', ItemPropertiesEditor);